@EnabledIfSystemProperty(named="s1.integration",matches="owned-run")
class Stage1StoreCoverageTest {
    @BeforeAll static void start()throws Exception{initialize();}
    @AfterAll static void end()throws Exception{finish();}
    @BeforeEach void refresh(){new Stage1PersistenceTest().freshManagerSessions();}
    @Test void closeAndRestoreNeverEraseRegulationOrRecreateMissingCooperationAndAllowOnlyCorrections()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();var other=ownerFixture();var revoked=employee(owner,List.of(roles(owner).get("INVENTORY")));var goods=Stage1SupplyMatrixTest.createGoods(owner,10,List.of("MERCHANT_DELIVERY"),true);String id=goods.getAsJsonObject("goods").get("id").getAsString(),sku=goods.getAsJsonArray("skus").get(0).getAsJsonObject().get("id").getAsString();var buyer=Stage1CrossHostTest.resident();assertEquals("PASS",Stage1CrossHostTest.precheck(owner,buyer,sku,"MERCHANT_DELIVERY",null,true).get("status").getAsString());
        var oldReview=db.required("SELECT * FROM li_p0_goods_review WHERE goods_id=?",id);var otherFacts=db.required("SELECT s.store_disable,c.version FROM li_store s JOIN li_p0_store_control c ON c.store_id=s.id WHERE s.id=?",other.store());
        call(post(Stage1Routes.STORE+"/staff/"+revoked.clerk()+"/revoke"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST整改不豁免撤权"),200);long version=db.count("SELECT version FROM li_p0_store_control WHERE store_id=?",owner.store());var command=map("requestId",req(),"expectedVersion",version,"reason","S1_TEST关闭整改");call(post(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/close"),operator,command,200);
        assertEquals("BLOCKED",Stage1CrossHostTest.precheck(owner,buyer,sku,"MERCHANT_DELIVERY",null,true).get("status").getAsString());call(get(Stage1Routes.STORE+"/goods"),revoked.login().session(),null,403);var corrective=login(owner.open()).session();assertEquals(oldReview,db.required("SELECT * FROM li_p0_goods_review WHERE goods_id=?",id));
        String agreement=String.valueOf(db.required("SELECT id FROM li_p0_agreement WHERE store_id=? AND confirmed_at IS NOT NULL",owner.store()).get("id"));call(post(Stage1Routes.MANAGER+"/agreements/"+agreement+"/terminate"),operator,map("requestId",req(),"expectedVersion",1,"reason","S1_TEST合作失效"),200);
        var q=call(get(Stage1Routes.STORE+"/qualifications"),corrective,null,200).getAsJsonArray("versions").get(0).getAsJsonObject().getAsJsonObject("details");var renewal=call(post(Stage1Routes.STORE+"/qualifications"),corrective,map("requestId",req(),"payload",map("qualifications",List.of(q))),200);call(post(Stage1Routes.STORE+"/qualifications/"+renewal.get("id").getAsString()+"/submit"),corrective,map("requestId",req(),"expectedVersion",0),200);
        call(post(Stage1Routes.STORE+"/goods/"+id+"/unlist"),corrective,map("requestId",req(),"expectedVersion",3),200);call(put(Stage1Routes.STORE+"/skus/"+sku+"/stock"),corrective,map("requestId",req(),"expectedVersion",1,"targetQuantity",5,"reason","S1_TEST仅减库"),200);call(put(Stage1Routes.STORE+"/skus/"+sku+"/stock"),corrective,map("requestId",req(),"expectedVersion",2,"targetQuantity",20,"reason","S1_TEST禁止扩售"),403);call(post(Stage1Routes.STORE+"/goods"),corrective,map("requestId",req(),"payload",map("name","S1_TEST新经营")),403);
        call(post(Stage1Routes.MANAGER+"/goods/"+id+"/force-off"),operator,map("requestId",req(),"expectedVersion",4,"reason","S1_TEST保留监管锁"),200);call(post(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/reopen"),operator,map("requestId",req(),"expectedVersion",version+1,"reason","S1_TEST仅恢复店铺"),200);
        assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("BASIC_ELIGIBLE"));call(post(Stage1Routes.STORE+"/goods/"+id+"/list"),corrective,map("requestId",req(),"expectedVersion",5),409);var current=call(get(Stage1Routes.STORE+"/goods/"+id),corrective,null,200).getAsJsonObject("goods");assertEquals("DOWN",current.get("marketStatus").getAsString());assertTrue(current.get("forcedOff").getAsBoolean());assertEquals(5,db.count("SELECT quantity FROM li_goods_sku WHERE id=?",sku));assertEquals(oldReview,db.required("SELECT * FROM li_p0_goods_review WHERE goods_id=?",id));assertEquals(otherFacts,db.required("SELECT s.store_disable,c.version FROM li_store s JOIN li_p0_store_control c ON c.store_id=s.id WHERE s.id=?",other.store()));
    }
    @Test void storeSupervisionNeedsReasonCurrentVersionAndOperatorGrantWithOneAuditWinner()throws Exception{
        var owner=ownerFixture();long version=db.count("SELECT version FROM li_p0_store_control WHERE store_id=?",owner.store());long audits=db.count("SELECT COUNT(*) FROM li_p0_audit WHERE object_id=?",owner.store());
        call(post(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/close"),operator,map("requestId",req(),"expectedVersion",version,"reason"," "),422);call(post(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/close"),channel,map("requestId",req(),"expectedVersion",version,"reason","S1_TEST资金角色不能关店"),403);
        var a=map("requestId",req(),"expectedVersion",version,"reason","S1_TEST关闭");var b=map("requestId",req(),"expectedVersion",version,"reason","S1_TEST恢复");var result=Stage1ConcurrencyTest.race(new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/stores/"+owner.store()+"/close",operator,a),new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/stores/"+owner.store()+"/reopen",operator,b));var winner=result.get(0)==200?a:b;String action=result.get(0)==200?"close":"reopen";
        call(post(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/"+action),operator,winner,200);assertEquals(version+1,db.count("SELECT version FROM li_p0_store_control WHERE store_id=?",owner.store()));assertEquals(audits+1,db.count("SELECT COUNT(*) FROM li_p0_audit WHERE object_id=?",owner.store()));var audit=db.required("SELECT actor_id,identity_domain,before_version,after_version,reason,created_at FROM li_p0_audit WHERE request_id=?",winner.get("requestId"));assertEquals(version,number(audit,"before_version"));assertEquals(version+1,number(audit,"after_version"));assertEquals("MANAGER",audit.get("identity_domain"));assertNotNull(audit.get("created_at"));assertEquals(winner.get("reason"),audit.get("reason"));
    }
    @Test void divergentStorePointersAndUniqueIndexesRejectAmbiguityWithoutChoosingOrDeletingEither()throws Exception{
        var owner=ownerFixture();var other=ownerFixture();String clerk=id(db.required("SELECT id FROM li_clerk WHERE store_id=? AND shopkeeper=1",owner.store()),"id");
        // Current Stage1 schema prevents two owner/Clerk rows for one Member. Keep
        // those constraints enabled; exercise inconsistent native pointers instead.
        assertThrows(org.springframework.dao.DuplicateKeyException.class,()->db.update("UPDATE li_store SET member_id=? WHERE id=?",owner.login().memberId(),other.store()));
        String otherClerk=id(db.required("SELECT id FROM li_clerk WHERE store_id=? AND shopkeeper=1",other.store()),"id");assertThrows(org.springframework.dao.DuplicateKeyException.class,()->db.update("UPDATE li_clerk SET member_id=? WHERE id=?",owner.login().memberId(),otherClerk));
        try{
            db.update("UPDATE li_clerk SET store_id=? WHERE id=?",other.store(),clerk);db.update("UPDATE li_member SET store_id=? WHERE id=?",other.store(),owner.login().memberId());var stores=db.rows("SELECT id,member_id,store_disable FROM li_store WHERE id IN (?,?) ORDER BY id",owner.store(),other.store());var clerks=db.rows("SELECT id,store_id,member_id,status FROM li_clerk WHERE member_id=? ORDER BY id",owner.login().memberId());
            var logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger("cn.lili.common.security.session.http.SessionSecurityAudit");var events=new ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>();events.start();logger.addAppender(events);try{var rejected=mvc.perform(get(Stage1Routes.STORE+"/context").header("accessToken",owner.login().session().accessToken())).andReturn().getResponse();assertEquals(403,rejected.getStatus());String audit=rejected.getHeader("X-Session-Audit-Id");assertNotNull(audit);assertTrue(events.list.stream().anyMatch(event->event.getFormattedMessage().contains("eventId="+audit)&&event.getFormattedMessage().contains("reason=DENIED")));assertTrue(events.list.stream().noneMatch(event->event.getFormattedMessage().contains(owner.login().session().accessToken())));}finally{logger.detachAppender(events);events.stop();}
            assertEquals(MerchantAccessException.Code.RELATION_CONFLICT,assertThrows(MerchantAccessException.class,()->login(owner.open())).getCode());call(get(Stage1Routes.STORE+"/context"),owner.login().session(),null,403);call(get(Stage1Routes.STORE+"/context").param("storeId",other.store()),owner.login().session(),null,403);call(post(Stage1Routes.STORE+"/goods"),owner.login().session(),map("requestId",req(),"payload",map("name","S1_TEST不得自动择店")),403);
            assertEquals(stores,db.rows("SELECT id,member_id,store_disable FROM li_store WHERE id IN (?,?) ORDER BY id",owner.store(),other.store()));assertEquals(clerks,db.rows("SELECT id,store_id,member_id,status FROM li_clerk WHERE member_id=? ORDER BY id",owner.login().memberId()));
        }finally{db.update("UPDATE li_clerk SET store_id=? WHERE id=?",owner.store(),clerk);db.update("UPDATE li_member SET store_id=? WHERE id=?",owner.store(),owner.login().memberId());}
        assertEquals("OWNER",login(owner.open()).role());assertEquals("OWNER",login(other.open()).role());
    }
    @Test void profileSameVersionRaceAndForeignStoreFieldsCannotOverwriteCurrentFacts()throws Exception{
        var owner=ownerFixture();var other=ownerFixture();long version=db.count("SELECT version FROM li_p0_store_control WHERE store_id=?",owner.store());var a=map("requestId",req(),"expectedVersion",version,"phone","010-11111111","contactName","S1_TEST联系人甲","businessHours","09:00-17:00","description","S1_TEST甲");var b=new LinkedHashMap<>(a);b.put("requestId",req());b.put("phone","010-22222222");
        Stage1ConcurrencyTest.race(new Stage1ConcurrencyTest.Command("PUT",Stage1Routes.STORE+"/profile",owner.login().session(),a),new Stage1ConcurrencyTest.Command("PUT",Stage1Routes.STORE+"/profile",owner.login().session(),b));assertEquals(version+1,db.count("SELECT version FROM li_p0_store_control WHERE store_id=?",owner.store()));var after=call(get(Stage1Routes.STORE+"/profile"),owner.login().session(),null,200);var foreign=new LinkedHashMap<>(a);foreign.put("storeId",owner.store());call(put(Stage1Routes.STORE+"/profile"),other.login().session(),foreign,422);assertEquals(after,call(get(Stage1Routes.STORE+"/profile"),owner.login().session(),null,200));
    }
}
